                        if [ "$ecosystem" = system ]; then
                            openssl x509 -inform DER -in "$work/original" -out "$work/system-match-1.pem" 2>/dev/null || { fail "Cannot stage DER system distrust: $bundle"; return; }
                        fi
                    fi
                fi;;
        esac
